from PIL import Image
from collections import deque
img=Image.open('/home/robot/captures/top_001.png').convert('L')
w,h=img.size
mask=[[0]*w for _ in range(h)]
for y in range(h):
    for x in range(w):
        mask[y][x]=1 if img.getpixel((x,y))>120 else 0
seen=[[False]*w for _ in range(h)]
comps=[]
for y in range(h):
    for x in range(w):
        if mask[y][x] and not seen[y][x]:
            q=deque([(x,y)]); seen[y][x]=True
            pixels=[]
            while q:
                cx,cy=q.popleft(); pixels.append((cx,cy))
                for nx,ny in ((cx+1,cy),(cx-1,cy),(cx,cy+1),(cx,cy-1)):
                    if 0<=nx<w and 0<=ny<h and mask[ny][nx] and not seen[ny][nx]:
                        seen[ny][nx]=True; q.append((nx,ny))
            if len(pixels)>5:
                sx=sum(p[0] for p in pixels)/len(pixels); sy=sum(p[1] for p in pixels)/len(pixels)
                comps.append((len(pixels),sx,sy,min(p[0] for p in pixels),max(p[0] for p in pixels),min(p[1] for p in pixels),max(p[1] for p in pixels)))
comps.sort(reverse=True)
print('num',len(comps))
for c in comps[:40]:
    print(c)
